import { test, expect } from '@playwright/test';

test.describe('Responsive Font Size', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://yourwebsite.com');
  });

  test('should display readable font size on small screens', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 }); // iPhone 6/7/8 size
    const fontSize = await page.locator('body').evaluate(el => window.getComputedStyle(el).fontSize);
    expect(parseFloat(fontSize)).toBeGreaterThan(16); // Assuming 16px is the minimum readable size
  });

  test('should not require zooming to read text', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });
    const textElement = page.getByText('Some important text');
    await expect(textElement).toBeVisible();
    const boundingBox = await textElement.boundingBox();
    expect(boundingBox).not.toBeNull();
    expect(boundingBox!.width).toBeGreaterThan(0);
  });
});
